&lt;li data-stringify-indent=&quot;2&quot; data-stringify-border=&quot;0&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;3:30am - 12pm CT &lt;/strong&gt;&lt;/li&gt;
&lt;li data-stringify-indent=&quot;2&quot; data-stringify-border=&quot;0&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;12pm - 8:30pm CT&lt;/strong&gt;&lt;/li&gt;
&lt;li data-stringify-indent=&quot;2&quot; data-stringify-border=&quot;0&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;2pm - 10:30pm CT&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
